import{_ as a,o as s,c as t,a5 as n}from"./chunks/framework.CslsFoWx.js";const g=JSON.parse('{"title":"Conformité fiscale","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/15-fiscal-compliance.md","filePath":"generated/modules/15-fiscal-compliance.md","lastUpdated":null}'),d={name:"modules/15-fiscal-compliance.md"};function r(i,e,l,o,p,c){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="conformite-fiscale" tabindex="-1">Conformité fiscale <a class="header-anchor" href="#conformite-fiscale" aria-label="Permalink to &quot;Conformité fiscale&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 1–2 · <a href="/VendoraSystem-docs/specs/15-fiscal-compliance">spécification complète</a></span></p><p>Module fiscal pluggable par pays qui scelle, archive et transmet sans toucher au flux de vente, sauf limite imposée par le pays (en Tunisie, pas de ticket sans signature du module fiscal). Le socle commun et le volet France sont livrés : ventes scellées et chaînées hors ligne, revérification serveur, clôtures J/M/A avec total perpétuel, mode formation, archive en format ouvert, JET, attestation PDF. Le volet Tunisie NACEF est cadré d&#39;après le cahier des charges officiel (révision du 17/11/2026 : le module de données fiscales du ministère signe chaque ticket) et reste à développer ; il attend, comme la certification, l&#39;attestation à valeur légale et l&#39;e-reporting réel, des actions extérieures.</p><div class="kpis"><div><b>10</b><span>faites</span></div><div><b>6</b><span>partielles</span></div><div><b>1</b><span>à faire</span></div><div><b>9</b><span>bloquées</span></div></div><h2 id="socle-commun" tabindex="-1">Socle commun <a class="header-anchor" href="#socle-commun" aria-label="Permalink to &quot;Socle commun&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Module fiscal par pays verrouillé</strong><br><span class="muted">Le module FR, TN ou NONE est déterminé pour le magasin et devient immuable dès la première vente réelle (409 FISCAL_LOCKED).<br><i>Pays déduit de la devise (fiscal_config.country_code) au lieu de Store.countryCode, API scopée /stores/{id}/fiscal/... : écarts à acter dans la spec 15.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-01, RG-FISC-02</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a></td></tr><tr><td><strong>Scellement chaîné des ventes</strong><br><span class="muted">Chaque vente réelle reçoit hors ligne un numéro fiscal sans trou par appareil et une empreinte SHA-256 chaînée à la précédente.<br><i>VEN-75 vague A (20/11/2026, staging) : l&#39;enregistrement passe en version 4 et porte la signature de la clé de la caisse (voir « Ventes et retours signés par la caisse »). Les enregistrements v1 à v3 se revérifient tels quels.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-FISC-04, RG-FISC-05, RG-FISC-66</td><td>1.x, 2.10, 2.28, VEN-75 (vague A)</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-appairage-ios">📷</a></td></tr><tr><td><strong>Ventes, retours, annulations et Z signés par la caisse</strong><br><span class="muted">Chaque vente, retour et annulation est scellé et signé par la clé Ed25519 de la caisse, et chaque rapport Z est signé et ancré à la chaîne des ventes ; le serveur vérifie les signatures et l&#39;ancre, signale toute anomalie (BAD_SEAL_SIGNATURE, CONTENT_MISMATCH, rétrogradation) sans jamais rejeter ni réécrire.<br><i>LIVRÉ EN VAGUES A ET B1 (20/11/2026, staging seulement). Vague A : enregistrement v4 (signatureAlg, signerKeyId, fiscalSignature) pour les ventes et les retours, iOS et Android ; clé publique exigée à l&#39;appairage (422 PUBLIC_KEY_REQUIRED) et pour pousser un enregistrement scellé (403 DEVICE_KEY_REQUIRED) ; vérification serveur par signerKeyId, BAD_SEAL_SIGNATURE (MISSING, INVALID, KEY_MISMATCH, UNKNOWN_KEY, UNSUPPORTED_ALGORITHM, DOWNGRADE), jamais de rejet ni de réécriture ; clé illisible = vente scellée sans signature et signalée. Vague B1 : l&#39;annulation après encaissement est un enregistrement scellé VOID aux montants inverses, signé, sur le numéro fiscal suivant (X, Z, clôtures et rapports gardent leurs totaux) ; le serveur le scelle dans la même chaîne et signale (CONTENT_MISMATCH, part VOID) une annulation qui contredit sa vente ; une vente déjà remboursée, même en partie, ne s&#39;annule plus ; le rapport Z est signé (v5) par la caisse (téléphone de salle et borne compris) et ancre la chaîne des ventes (premier et dernier numéro, dernière empreinte) ; le serveur vérifie la signature et confronte l&#39;ancre aux ventes reçues (CHAIN_ANCHOR, SIGNER) ; non-rétrogradation par chaîne ; archive : annulations dans ventes.csv, signature des Z dans rapports_z.csv. RESTE, non livré : vague B2 (PIN de la confirmation manuelle de la borne, une phrase par cause de CONTENT_MISMATCH au back-office, alerte visible pour une annulation sans maillon) ; vague C (contrôle de la chaîne sur l&#39;appareil, témoins contre la restauration d&#39;une base, écran « intégrité locale compromise », CHAIN_FORK, niveau fiscal déclaré par l&#39;app) ; VEN-76 (ancre des clés publiques hors de la base, clôtures, journal technique et archives signés par le serveur). Tunisie : l&#39;annulation sera émise comme transaction « Remboursement » (VEN-67), le type VOID reste interne. Aucune certification ni homologation : le mode de preuve français n&#39;est pas choisi et l&#39;homologation NACEF n&#39;est pas déposée. Limite connue : une app installée avant le lot ne peut plus s&#39;appairer (clé exigée), et ordre de déploiement : serveur B1 avant les apps B1.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-FISC-05, RG-FISC-62, RG-FISC-66, RG-FISC-61</td><td>VEN-75 (vague A), VEN-75 (vague B1)</td><td></td></tr><tr><td><strong>Zone fiscale du ticket</strong><br><span class="muted">Le ticket affiche le numéro fiscal et l&#39;empreinte abrégée, et la caisse confirme « Vente scellée — n° fiscal N ».</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-FISC-05</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-ios">📷</a></td></tr><tr><td><strong>Revérification serveur au push</strong><br><span class="muted">Le serveur revérifie l&#39;empreinte, la continuité par appareil, la signature de la caisse (ventes, retours, annulations, rapports Z) et l&#39;ancre du Z, et rejoue le moteur partagé ; une anomalie est signalée, jamais réécrite.<br><i>VEN-75 vague A (20/11/2026, staging) : vérification de la signature par signerKeyId, anomalie BAD_SEAL_SIGNATURE (dont DOWNGRADE : vente non signée après une vente signée du même appareil, ou venant d&#39;un appareil appairé avec sa clé), vente jamais rejetée ni réécrite. Vague B1 : annulation (VOID) scellée dans la même chaîne, CONTENT_MISMATCH (part VOID) si elle contredit sa vente, suit un premier VOID ou vise une vente déjà remboursée ; Z v5 : signature vérifiée, signataire (part SIGNER) et ancre de la chaîne confrontée aux ventes reçues (part CHAIN_ANCHOR), non-rétrogradation par chaîne, portée Z_REPORT. Limites : la première annulation d&#39;un appareil, l&#39;annulation d&#39;une vente en quarantaine et l&#39;ancre tant qu&#39;une vente de la caisse attend ne sont pas jugées ; alerte visible pour une annulation sans maillon en vague B2. CHAIN_FORK : vague C, non livré.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-05, RG-FISC-12, RG-FISC-62</td><td>1.x, 2.20, VEN-75 (vague A), VEN-75 (vague B1)</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-android">📷</a></td></tr><tr><td><strong>Corrections en plus ou en moins</strong><br><span class="muted">Une erreur se corrige par une annulation ou un retour motivé, scellé, signé et chaîné, référençant la vente d&#39;origine ; une vente déjà remboursée ne s&#39;annule plus.<br><i>VEN-75 vague B1 (20/11/2026, staging) : l&#39;annulation après encaissement est un enregistrement scellé VOID, signé, aux montants inverses, sur le numéro fiscal suivant ; une vente déjà remboursée, même en partie, ne s&#39;annule plus (le reste se rend par un retour) ; la purge d&#39;un ticket en attente ne consomme aucun numéro fiscal.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-03</td><td>2.20, 2.23, VEN-75 (vague B1)</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-annulations-retours">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr><tr><td><strong>Clôtures journalières, mensuelles, annuelles</strong><br><span class="muted">Le serveur génère automatiquement les clôtures J/M/A, y compris « néant », chaînées par niveau.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-06, RG-FISC-08</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a></td></tr><tr><td><strong>Total perpétuel</strong><br><span class="muted">Chaque clôture embarque un total perpétuel depuis la première vente réelle, jamais remis à zéro ni purgé.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-07</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a></td></tr><tr><td><strong>Export PDF des clôtures</strong><br><span class="muted">Le gérant télécharge le registre des clôtures en PDF, avec totaux de période, perpétuel et empreintes.<br><i>Le PDF d&#39;une clôture individuelle avec le détail des Z agrégés n&#39;est pas fait.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-06</td><td>2.19</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-export-pdf-z">📷</a></td></tr><tr><td><strong>Mode formation factice</strong><br><span class="muted">Sous PIN manager, une caisse passe en formation : bandeau permanent, tickets « FACTICE - FORMATION », ventes exclues de tous les totaux réels. Une commande réelle (addition, borne) ne s&#39;encaisse jamais en formation et aucun paiement externe (QR, fournisseur, terminal piloté) n&#39;est proposé.<br><i>Le refus « Clôturez la session » n&#39;apparaît qu&#39;après la saisie du PIN (pré-contrôle à faire) ; activation depuis l&#39;appareil seulement, le back-office liste les caisses en formation. Restes avant la production : relais du hub local depuis une caisse d&#39;ancienne version, annulation ou offert de lignes d&#39;une vraie addition en formation.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-09, RG-CHAN-35</td><td>1.x, 4.2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-formation-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-formation-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-12-4.2-v0">📷</a></td></tr><tr><td><strong>Archive fiscale en format ouvert</strong><br><span class="muted">Le propriétaire génère et télécharge pour une période close un ZIP de CSV avec notice en français et manifeste d&#39;empreintes chaîné ; les ventes, retours et annulations y portent leur signature, leur signataire et leur contenu canonique, et les rapports Z leur signature, avec les clés publiques.<br><i>09/11 : POST …/fiscal/archives → 202 et statut PENDING → READY / FAILED (JET ARCHIVE_FAILED), reprise au redémarrage, téléchargement refusé (409) tant que l&#39;archive n&#39;est pas prête ; back-office FR / EN / AR ; V87. VEN-75 vague A (20/11/2026, staging) : ventes.csv gagne type, algorithme_signature, signer_key_id, signature et contenu_canonique ; nouveau fichier cles_publiques.csv ; l&#39;outil de vérification revérifie empreintes, chaînage et signatures à partir du fichier seul. Vague B1 : les annulations figurent dans ventes.csv, la signature des Z dans rapports_z.csv, et l&#39;outil de vérification est étendu. Limite : les clés publiques viennent de la base du serveur (ancre hors base : VEN-76).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-10, RG-FISC-62</td><td>1.x, cartes-09/11, VEN-75 (vague A), VEN-75 (vague B1)</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-09-archive-asynchrone-purge">📷</a></td></tr><tr><td><strong>Conservation au moins 6 ans</strong><br><span class="muted">Les données fiscales sont conservées au moins 6 ans côté serveur ; au-delà, le détail n&#39;est purgé que sous une archive scellée, de façon tracée.<br><i>09/11 : purge du détail de plus de 6 ans seulement si une archive scellée couvre la période (empreintes revérifiées), registre des purges et JET PURGE ; clôtures, total perpétuel et Z intacts ; désactivée par défaut, <code>POS_FISCAL_PURGE_ENABLED=true</code> en production.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-FISC-13, RG-FISC-11</td><td>1.x, cartes-09/11</td><td><a href="/VendoraSystem-docs/preuves/2026-11-09-archive-asynchrone-purge">📷</a></td></tr><tr><td><strong>Journal des événements techniques (JET)</strong><br><span class="muted">Le JET append-only trace ruptures de chaîne, mode formation, verrouillage de configuration, archives, annulations et retours.<br><i>09/11 : types ARCHIVE_FAILED et PURGE émis. Les types APP_UPDATED (mise à jour de version) et CLOCK_SUSPECT (horloge suspecte) ne sont pas émis. 11/11 : 17 types d&#39;événements avec un libellé traduit (FR / EN / AR), détails redits dans la langue du back-office ; restent les détails des événements e-reporting.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-11</td><td>1.x, 2.20, cartes-09/11, cartes-11/11</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-09-archive-asynchrone-purge">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-11-anomalies-fiscales">📷</a></td></tr><tr><td><strong>Rapport d&#39;intégrité et alertes</strong><br><span class="muted">Le gérant consulte l&#39;intégrité des chaînes et voit les anomalies de scellement dans les alertes du tableau de bord.<br><i>11/11 : anomalies structurées (code stable + paramètres), relues du texte stocké sans réécriture ; phrases claires FR / EN / AR avec la caisse par son nom, conseil d&#39;action et code technique en petit, sur Conformité fiscale, Rapports Z, tableau de bord et PDF du Z. VEN-75 vague A (20/11/2026) : nouveau code BAD_SEAL_SIGNATURE dans l&#39;API publique d&#39;intégrité (docs/API-PUBLIQUE.md et OpenAPI à jour). Vague B1 : le compteur « Enregistrements scellés » compte ventes, retours et annulations ; libellés FR / EN / AR des nouvelles anomalies (annulation, signature et ancre du Z). Restes : une phrase par cause de CONTENT_MISMATCH et alerte visible pour une annulation sans maillon (vague B2) ; CHAIN_FORK (vague C).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-12, RG-FISC-62</td><td>1.x, 2.23, cartes-11/11, VEN-75 (vague A), VEN-75 (vague B1)</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-11-anomalies-fiscales">📷</a></td></tr><tr><td><strong>Signature des lots push vérifiée par le serveur</strong><br><span class="muted">Les événements poussés sont signés Ed25519 par l&#39;appareil et la signature est vérifiée et conservée par le serveur.<br><i>Fait : identité Ed25519 par appareil (lot 2.28, signature sur le LAN) ; vérification des lots push au serveur depuis le lot R6 (SyncService : 403 BAD_SIGNATURE si le lot est non signé ou mal signé alors que la clé est enregistrée, rien n&#39;est enregistré, signature gardée dans event_log) ; depuis VEN-75 vague A, un lot qui porte un enregistrement fiscal d&#39;un appareil sans clé enregistrée est refusé entier (403 DEVICE_KEY_REQUIRED). Même fonction que la fiche de la spec 10.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SYNC-20</td><td>2.28, R6, VEN-75 (vague A)</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-identite-appareil">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r6-synchro">📷</a></td></tr></tbody></table><h2 id="volet-france" tabindex="-1">Volet France <a class="header-anchor" href="#volet-france" aria-label="Permalink to &quot;Volet France&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Attestation individuelle nominative</strong><br><span class="muted">Le propriétaire télécharge en un clic une attestation PDF conforme au modèle BOI-LETTRE-000242 pour sa version majeure.<br><i>PDF généré avec registre, mais marqué « MODÈLE » sans valeur légale tant que l&#39;identité de l&#39;éditeur (nom du produit et société) n&#39;est pas décidée.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-21, RG-FISC-23</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a></td></tr><tr><td><strong>Dossier de certification NF525 / LNE</strong><br><span class="muted">Le dossier de certification (matrice des exigences ISCA, jeux de preuve, procédures) est préparé pour un organisme accrédité.<br><i>Non fait ; dépend d&#39;un organisme accrédité, visé avant toute commercialisation en France.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-FISC-20, RG-FISC-22</td><td></td><td></td></tr><tr><td><strong>Hook e-reporting B2C</strong><br><span class="muted">Le module FR fournit les agrégats journaliers de TVA issus des clôtures pour la transmission via une plateforme agréée.<br><i>Lot 3.15 (05/11/2026) : agrégats lus dans les lignes de vente (même source que les clôtures journalières, scellement du jour indiqué), connecteur EReportingPlatform côté serveur avec plateforme simulée ; les vraies plateformes se branchent avec leurs clés (action terrain).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-FISC-24</td><td>3.15</td><td><a href="/VendoraSystem-docs/preuves/2026-11-05-315-e-reporting">📷</a></td></tr></tbody></table><h2 id="volet-tunisie-nacef" tabindex="-1">Volet Tunisie (NACEF) <a class="header-anchor" href="#volet-tunisie-nacef" aria-label="Permalink to &quot;Volet Tunisie (NACEF)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Intégration du module de données fiscales</strong><br><span class="muted">Vendora est le module de caisse ; le module de données fiscales (S-MDF fourni par le ministère, ou boîtier E-MDF) signe les tickets, produit le QR et transmet à NACEF. La caisse pilote sa mise en service : certificat, synchronisation, ticket zéro.<br><i>Cahier des charges NACEF v1.2 lu le 17/11/2026 : remplace l&#39;ancien « module de sécurisation » (RG-FISC-30). Hypothèse du 18/11/2026 : un mini-ordinateur « serveur fiscal » par restaurant (RG-FISC-60). Attend le kit d&#39;intégration et le prototype (VEN-61, VEN-64, VEN-65).</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-FISC-40, RG-FISC-41, RG-FISC-42, RG-FISC-43</td><td></td><td></td></tr><tr><td><strong>Signature de chaque ticket et QR du module fiscal</strong><br><span class="muted">Chaque ticket d&#39;un magasin tunisien est signé par le module de données fiscales, qui rend l&#39;identifiant fiscal et le QR à imprimer. Sans signature, pas de ticket : la caisse le dit clairement et indique quoi faire.<br><i>Le QR n&#39;est plus composé par Vendora (révision du 17/11/2026, RG-FISC-31 remplacée). Règle de blocage à confirmer au prototype (VEN-64, VEN-65, VEN-68).</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-FISC-44, RG-FISC-45</td><td></td><td></td></tr><tr><td><strong>Contenu du ticket tunisien</strong><br><span class="muted">Le ticket porte les mentions du cahier des charges : matricule fiscal, IMDF, caisse et version, agent, type de ticket, client, familles d&#39;articles, taxes par code (droit de timbre compris), modes de paiement, référence du module fiscal. Copie numérotée, pro-forma, remboursement et formation sont des opérations enregistrées.<br><i>RG-FISC-32 remplacée. Schéma JSON officiel à récupérer (VEN-61) ; VEN-66, VEN-67, VEN-68.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-FISC-47, RG-FISC-48, RG-FISC-49, RG-FISC-50, RG-FISC-51, RG-FISC-52</td><td></td><td></td></tr><tr><td><strong>Mode hors ligne borné par le module fiscal</strong><br><span class="muted">Sans accès à NACEF, le module fiscal continue de signer dans une limite (nombre de tickets, fenêtre de 3 jours). La caisse affiche le compte restant, prévient avant la limite, et le propriétaire resynchronise avec son PIN et un code SMS.<br><i>Remplace « transmission quasi temps réel à NACEF » (RG-FISC-33) : c&#39;est le module fiscal qui transmet, pas Vendora (révision du 17/11/2026). VEN-65, VEN-69.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-FISC-46</td><td></td><td></td></tr><tr><td><strong>Piste d&#39;audit NACEF</strong><br><span class="muted">La caisse trace toutes les opérations (accès, encaissement, paramètres avec valeurs avant et après, imprimante, hors ligne, mises à jour) au format du cahier des charges, les envoie au module fiscal et les exporte en archive.<br><i>Remplace la file fiscal_outbox (RG-FISC-34), abandonnée le 17/11/2026. VEN-70.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-FISC-53</td><td></td><td></td></tr><tr><td><strong>Calendrier d&#39;obligation</strong><br><span class="muted">Le module TN s&#39;active pour les magasins de profil restaurant et le back-office informe du calendrier légal.<br><i>Sociétés déjà dans l&#39;obligation (01/11/2025 puis 01/07/2026) ; personnes physiques au régime réel le 01/07/2027, les autres le 01/07/2028. Dépend du volet NACEF.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-FISC-35, RG-FISC-36</td><td></td><td></td></tr><tr><td><strong>Accréditation du fournisseur et homologation de la caisse</strong><br><span class="muted">L&#39;éditeur obtient d&#39;abord l&#39;accréditation (contribuable tunisien, assistance, maintenance, contrôle sur place), puis l&#39;homologation de la caisse : six dossiers en français et le tableau des exigences. Il déclare ensuite chaque caisse vendue et chaque maintenance.<br><i>RG-FISC-38 remplacée. Décision d&#39;Ahmed du 17/11/2026 : accréditation à engager. VEN-62, VEN-72, VEN-73.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-FISC-58</td><td></td><td></td></tr><tr><td><strong>Hook El Fatoora (TEIF / TTN)</strong><br><span class="muted">Le module TN exporte les factures au format TEIF signé via TTN pour les clients assujettis.<br><i>Phase 4 (spec 12, AMEL-10).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-FISC-37</td><td></td><td></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Attestation FR à valeur légale : bloquée par l&#39;identité de l&#39;éditeur (nom du produit et société).</li><li>Dossier de certification NF525 / LNE et hook e-reporting B2C (spec 12, plateforme agréée).</li><li>PDF d&#39;une clôture individuelle ; types JET APP_UPDATED et CLOCK_SUSPECT.</li><li>Mode formation : pré-contrôle « clôturez la session » avant la saisie du PIN.</li><li>Signature Ed25519 des lots push vérifiée par le serveur (event_log.signature).</li><li>Acter dans la spec 15 l&#39;API scopée /stores/{id}/fiscal/... et fiscal_config.country_code.</li><li>El Fatoora (TEIF / TTN) en phase 4.</li><li>Mode formation : refuser l&#39;annulation et l&#39;offert de lignes d&#39;une vraie addition ; filtrer au hub local l&#39;OrderPaid de formation d&#39;une caisse d&#39;ancienne version.</li><li>Volet Tunisie NACEF : spec révisée le 17/11/2026 d&#39;après le cahier des charges v1.2 ; hypothèse du 18/11/2026 : un mini-ordinateur « serveur fiscal » par restaurant ; développement en attente du kit d&#39;intégration, du prototype et de l&#39;accréditation (VEN-61 à 73).</li><li>VEN-75 : annulations et rapports Z signés par la caisse (vague B) ; contrôle d&#39;intégrité sur l&#39;appareil, témoins, écran « intégrité locale compromise » et CHAIN_FORK (vague C) ; ancre des clés publiques hors de la base (VEN-76).</li></ul>',12)])])}const m=a(d,[["render",r]]);export{g as __pageData,m as default};
